head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60205";
scwin.xmlHttp = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isExaService

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60205.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_16", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '1'); } }, { id: "c_when_18", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '2'); } }, { id: "c_when_20", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '6'); } }, { id: "c_when_35", fn: function(){ return ((dma_pageContext.get("isExaService") ?? "") === 'Y'); } }, { id: "c_otherwise_50", fn: function(){ return (!(((dma_pageContext.get("isExaService") ?? "") === 'Y'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurcd", fn: function () { return String(String((dma_pageContext.get("isurcd") ?? ""))); } },
        { childId: "ipt_isurcd2", fn: function () { return String(String((dma_pageContext.get("isurcd") ?? ""))); } },
        { childId: "ipt_isurCd", fn: function () { return String(String((dma_pageContext.get("isurcd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent("tabContents").setStyle("display", "none");
        /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        await scwin.fnSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60205.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
