        await scwin.fnTabView(2)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60205.tabView_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearchPresentPrice_ajaxsubmit
 * @description fn Search Present Price ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchPresentPrice_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearchPresentPrice_ajaxsubmit",
        method: "post",
        action: "/corpdetail/chart.do",
        ref: "dma_fnSearchPresentPriceAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearchDisclsChartInfo_ajaxsubmit
 * @description fn Search Discls Chart Info ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchDisclsChartInfo_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearchDisclsChartInfo_ajaxsubmit",
        method: "post",
        action: "/corpdetail/chart.do",
        ref: "dma_fnSearchDisclsChartInfoAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearchCorpBasicInfo_rawxhr
 * @description fn Search Corp Basic Info rawxhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchCorpBasicInfo_rawxhr = async function () {
    const sbmOptions = {
        id: "tx_fnSearchCorpBasicInfo_rawxhr",
        method: "post",
        action: "/common/corpbasicinfo.do?method=searchCorpBasicInfo&cd_or_nm=",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initComNmSetting
 * @description init Com Nm Setting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initComNmSetting = async function () {
    const comnm = scwin.getRecentCompanyFromCookie();
    if (comnm !== null && comnm !== "") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comnm);
        await scwin.fnSearchCorpBasicInfo();
    }
};

/**
 * @method
 * @name fnTabView
 * @description fn Tab View 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabView = async function (idx) {
    $(document).find("li[id=tabView]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            } else {
                if ($(this).hasClass("active")) {
                    $(this).removeClass("active");
                }
            }
    });
    if (idx === "0") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForDisclsAnalysisChart");
    } else {
        if (idx === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIdxComparisonChart");
        } else {
            if (idx === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIssueComparisonChart");
            }
        }
    }
    await scwin.fnSearchDisclsChartInfo();
};

/**
 * @method
 * @name getRecentCompanyFromCookie
 * @description get Recent Company From Cookie 처리
 * @returns {void}
 * @hidden N
 */
scwin.getRecentCompanyFromCookie = function () {
    const cookies = scwin.fnGetCookie('krxComp');
    const item = null;
    let userCompaniesArray = null;
    let tmpstr = null;
    if (cookies !== null) {
        userCompaniesArray = cookies.split("/");
    }
    const issues = "";
    tmpstr = "";
    if (userCompaniesArray !== null && userCompaniesArray !== "") {
        tmpstr = userCompaniesArray[0].split(",");
    }
    return tmpstr[2];
};

/**
 * @method
 * @name fnGetCookie
 * @description fn Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent("tabContents").setStyle("display", "");
    await scwin.fnSearchPresentPrice();
    await scwin.fnSearchDisclsChartInfo();
};

/**
 * @method
 * @name fnSearchPresentPrice
 * @description fn Search Present Price 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchPresentPrice = async function () {
    await scwin.tx_fnSearchPresentPrice_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchPresentPriceCallBack
 * @description fn Search Present Price Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchPresentPriceCallBack = function (data) {
    $("#mainContentsPrice").empty().append(data);
};

/**
 * @method
 * @name fnSearchDisclsChartInfo
 * @description fn Search Discls Chart Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchDisclsChartInfo = async function () {
    await scwin.tx_fnSearchDisclsChartInfo_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchViewCallBack
 * @description fn Search View Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchViewCallBack = function (data) {
    $("#mainContentsView").empty().append(data);
};

/**
 * @method
 * @name fnSearchCorpBasicInfo
 * @description fn Search Corp Basic Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpBasicInfo = async function () {
    let cd_or_nm = ($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("comAbbrv") || '');
    if (cd_or_nm === "") {
        await $c.win.alert("회사명 또는 종목코드를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    cd_or_nm = cd_or_nm.replace(/\&/gi, '#amp#');
    cd_or_nm = cd_or_nm.replace(/\+/gi, '#plus#');
    await scwin.tx_fnSearchCorpBasicInfo_rawxhr();
};

/**
 * @method
 * @name createXMLHttpRequest
 * @description create XMLHttp Request 처리
 * @returns {void}
 * @hidden N
 */
scwin.createXMLHttpRequest = function () {
    let xmlHttp = null;
    if (XMLHttpRequest) {
        xmlHttp = new XMLHttpRequest();
    }
    return xmlHttp;
};

/**
 * @method
 * @name handleStateChange
 * @description handle State Change 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.handleStateChange = async function () {
    if (scwin.xmlHttp.readyState === 4) {
        if (scwin.xmlHttp.status === 200) {
            await scwin.fnSetCorpBasicInfo();
        }
    }
};

/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function () {
    if (($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("isurCd") || '') !== "" && ($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("comAbbrv") || '') !== "") {
        await scwin.fnSearch();
        return;
    }
    const responseXML = scwin.xmlHttp.responseXML;
    const element = responseXML;
    const nodeList = element.getElementsByTagName("item");
    const node = nodeList[0];
    let state = null;
    let isurcd = null;
    let spotisutrdmkttpcd = null;
    let comabbr = null;
    let kiscomcd = null;
    let fssunqno = null;
    let repisucd = null;
    let repisusrtcd = null;
    let corpcount = 0;
    const repisusrtkornm = null;
    state = node.getElementsByTagName("state")[0].firstChild.nodeValue;
    if (state === "1") {
        if (node.getElementsByTagName("isurcd")[0].firstChild !== null) {
            isurcd = node.getElementsByTagName("isurcd")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("spotisutrdmkttpcd")[0].firstChild !== null) {
            spotisutrdmkttpcd = node.getElementsByTagName("spotisutrdmkttpcd")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("comabbr")[0].firstChild !== null) {
            comabbr = node.getElementsByTagName("comabbr")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("kiscomcd")[0].firstChild !== null) {
            kiscomcd = node.getElementsByTagName("kiscomcd")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("fssunqno")[0].firstChild !== null) {
            fssunqno = node.getElementsByTagName("fssunqno")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("repisucd")[0].firstChild !== null) {
            repisucd = node.getElementsByTagName("repisucd")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("repisusrtcd")[0].firstChild !== null) {
            repisusrtcd = node.getElementsByTagName("repisusrtcd")[0].firstChild.nodeValue;
        }
        if (node.getElementsByTagName("corpcount")[0].firstChild !== null) {
            corpcount = node.getElementsByTagName("corpcount")[0].firstChild.nodeValue;
        }
        if (corpcount > 1) {
            scwin.fnCommFindCorpName();
            return;
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        if (spotisutrdmkttpcd === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "stock");
        } else {
            if (spotisutrdmkttpcd === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "kosdaq");
            } else {
                if (spotisutrdmkttpcd === "6") {
                    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "konex");
                }
            }
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("repIsuCd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        await scwin.fnSearch();
    } else {
        await $c.win.alert("해당 회사가 존재하지 않습니다.");
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", '');
    }
};

/**
 * @method
 * @name fnCommFindCorpName
 * @description fn Comm Find Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCommFindCorpName = function () {
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("searchCorpMode", "");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnFindCorpName2( " ') */
};

/**
 * @method
 * @name setCorpInfo2
 * @description set Corp Info2 처리
 * @param {*} isurcd isurcd
 * @param {String} kisComCd kisComCd
 * @param {*} repisucd repisucd
 * @param {*} repisukornm repisukornm
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} ipt_comAbbrv ipt_comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} ipt_markettype ipt_markettype
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo2 = function (isurcd, kisComCd, repisucd, repisukornm, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo, ipt_markettype) {
    if (($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("searchCorpMode") || '') === 'Y') {
        setAddCorpInfo(isurcd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo);
        return;
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", ipt_comAbbrv);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisukornm);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", ipt_comAbbrv);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisukornm);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", ipt_markettype);
    if (ipt_markettype === "1") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "stock");
    } else {
        if (ipt_markettype === "2") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "kosdaq");
        } else {
            if (ipt_markettype === "6") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "konex");
            }
        }
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", ipt_markettype);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("repIsuCd", repisucd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", ipt_comAbbrv);
};

